// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vBzProcsNo;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.rowPos;
scwin.gUsrId = js_id; // 세션 사용자ID
scwin.vScrenID = "ULDSTF05015.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchSecuIsu = function() {
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    var url;
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=KONEX_SECU_ISU_DTL" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstlst.select.konex.secuisudtl" + "&{P}param01=" + scwin.vBzProcsNo; //  접수번호

    dts_secuIsu.DataID = encodeURI(url);
    dts_secuIsu.reset();
    if (dts_secuIsu.getTotalRow() == 0) {
        buttonSet.setInsertStatus();
        dts_secuIsu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KONEX_SECU_ISU_DTL";
        dts_secuIsu.reset();
        dts_secuIsu.insertRow();
        $c.stf.setObjectValue(chk_secuYn, 'Y');
        dts_secuIsu.setCellData("1", "KONEX_SECU_ISU_METHD_TP_CD", "1");
        dts_secuIsu.setCellData("1", "ISU_SCHDL_STK_KIND_CD", "00");
        $c.stf.setObjectValue(edt_ISU_SCHDL_SHRS, '');
        $c.stf.setObjectValue(edt_ISU_NXT_SHRS, '');
        $c.stf.setObjectValue(edt_ISU_NXT_CAP, '');
        $c.stf.setObjectValue(edt_PAY_SCHDL_DD, '');
    } else {
        if (dts_secuIsu.getCellData(1, "KONEX_SECU_ISU_YN") == "Y") {
            $c.stf.showObj(pan_secu, true);
            $c.stf.setObjectValue(chk_secuYn, 'Y');
        } else {
            $c.stf.showObj(pan_secu, false);
            $c.stf.setObjectValue(chk_secuYn, 'N');
            $c.stf.setObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD, '');
            $c.stf.setObjectValue(cmb_ISU_SCHDL_STK_KIND_CD, '');
            $c.stf.setObjectValue(edt_ISU_SCHDL_SHRS, '');
            $c.stf.setObjectValue(edt_ISU_NXT_SHRS, '');
            $c.stf.setObjectValue(edt_ISU_NXT_CAP, '');
            $c.stf.setObjectValue(edt_PAY_SCHDL_DD, '');
        }
        buttonSet.setUpdateStatus();
    }
};
scwin.fn_searchCode = function() {
    /*
    03346 - 코넥스증권발행방식
    00391 - 주식종류
    */
    var arrCid = [{
        cid: "KONEX_SECU_ISU_METHD_TP_CD",
        cnm: "cmb_KONEX_SECU_ISU_METHD_TP_CD"
    }, {
        cid: "STK_KIND_CD",
        cnm: "cmb_ISU_SCHDL_STK_KIND_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='KONEX_SECU_ISU_METHD_TP_CD','STK_KIND_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_secuIsu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        //		alert("dts_secuIsu :"+dts_secuIsu.Text);
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_secuIsu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var secuYn = $c.stf.getObjectValue(chk_secuYn);
    if (secuYn == "Y") {
        dts_secuIsu.setCellData(1, "KONEX_SECU_ISU_YN", "Y");
        if ($c.stf.getObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD) == '') {
            $c.win.alert('증권발행방식이 입력되지 않았습니다.');
            cmb_KONEX_SECU_ISU_METHD_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_ISU_SCHDL_STK_KIND_CD) == '') {
            $c.win.alert('발행예정주식종류가 입력되지 않았습니다.');
            cmb_ISU_SCHDL_STK_KIND_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ISU_SCHDL_SHRS) == '') {
            $c.win.alert('발행예정주식수가 입력되지 않았습니다.');
            edt_ISU_SCHDL_SHRS.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ISU_NXT_SHRS) == '') {
            $c.win.alert('발행후주식수가 입력되지 않았습니다.');
            edt_ISU_NXT_SHRS.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ISU_NXT_CAP) == '') {
            $c.win.alert('발행후자본금이 입력되지 않았습니다.');
            edt_ISU_NXT_CAP.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_PAY_SCHDL_DD) == '') {
            $c.win.alert('납입예정일자가 입력되지 않았습니다.');
            edt_PAY_SCHDL_DD.focus();
            return false;

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

        } /*ORG SRC: dts_secuIsu.nameValue("1", "KONEX_SECU_ISU_METHD_TP_CD") = getObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD);*/ X = $c.stf.getObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_STK_KIND_CD") = getObjectValue(cmb_ISU_SCHDL_STK_KIND_CD);*/ X = $c.stf.getObjectValue(cmb_ISU_SCHDL_STK_KIND_CD); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_SHRS") = getObjectValue(edt_ISU_SCHDL_SHRS);*/ X = $c.stf.getObjectValue(edt_ISU_SCHDL_SHRS); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_SHRS") = getObjectValue(edt_ISU_NXT_SHRS);*/ X = $c.stf.getObjectValue(edt_ISU_NXT_SHRS); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_CAP") = getObjectValue(edt_ISU_NXT_CAP);*/ X = $c.stf.getObjectValue(edt_ISU_NXT_CAP); /*ORG SRC: dts_secuIsu.nameValue("1", "PAY_SCHDL_DD") = getObjectValue(edt_PAY_SCHDL_DD);*/ X = $c.stf.getObjectValue(edt_PAY_SCHDL_DD);
    } else {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_secuIsu.setCellData(1, "KONEX_SECU_ISU_YN", "N"); /*ORG SRC: dts_secuIsu.nameValue("1", "KONEX_SECU_ISU_METHD_TP_CD") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_STK_KIND_CD") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_SHRS") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_SHRS") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_CAP") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "PAY_SCHDL_DD") = '';*/ X = '';
    }
    return true;
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/Newlisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveKonexSecuIsu");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_secuIsu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo;
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_read_sync = $c.frame.path("../").fn_read_sync;
    fr_fn_read_sync();
};
scwin.chk_secuYn_onclick = function() {
    if ($c.stf.getObjectValue(chk_secuYn) == "Y") {
        $c.stf.showObj(pan_secu, true);
        $c.stf.setObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD, '1');
        $c.stf.setObjectValue(cmb_ISU_SCHDL_STK_KIND_CD, '00');
    } else {
        $c.stf.showObj(pan_secu, false);
        /*dts_secuIsu.setNameValue(1, "KONEX_SECU_ISU_METHD_TP_CD","") ;
        dts_secuIsu.setNameValue(1, "ISU_SCHDL_STK_KIND_CD","") ;
        dts_secuIsu.setNameValue(1, "ISU_SCHDL_SHRS","") ;
        dts_secuIsu.setNameValue(1, "ISU_NXT_SHRS","") ;
        dts_secuIsu.setNameValue(1, "ISU_NXT_CAP","") ;
        dts_secuIsu.setNameValue(1, "PAY_SCHDL_DD","") ;*/
        $c.stf.setObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD, '');
        $c.stf.setObjectValue(cmb_ISU_SCHDL_STK_KIND_CD, '');
        $c.stf.setObjectValue(edt_ISU_SCHDL_SHRS, '');
        $c.stf.setObjectValue(edt_ISU_NXT_SHRS, '');
        $c.stf.setObjectValue(edt_ISU_NXT_CAP, '');
        $c.stf.setObjectValue(edt_PAY_SCHDL_DD, '');
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("증권발행정보 저장에 실패 하였습니다.");
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("증권발행정보가 저장되었습니다.");
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame(); //self.close();

};
scwin.gform_onload = function() {
    $c.elw.fn_searchCode();
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정

    scwin.fn_searchSecuIsu();
};
scwin.img_PAY_SCHDL_DD_onclick = function() {
    popUpCalendar2(edt_PAY_SCHDL_DD);
};
